const WhatsAppNotify={get API_URL(){return window.STEMULUS_BOT_URL||null},get API_KEY(){return window.STEMULUS_CONFIG&&window.STEMULUS_CONFIG.notifyKey||null},get isConfigured(){return Boolean(this.API_URL)},async sendBookingNotification(t){return this.post("booking",t)},async sendEnrollmentNotification(t){return this.post("enrollment",t)},async sendContactNotification(t){return this.post("contact",t)},async post(t,n){if(!this.isConfigured)return{success:!1,error:"WhatsApp notification service not configured"};try{const o={"Content-Type":"application/json"};this.API_KEY&&(o["x-api-key"]=this.API_KEY);const i=await fetch(this.API_URL,{method:"POST",headers:o,body:JSON.stringify({type:t,...n})});return await i.json()}catch(t){return{success:!1,error:t.message}}}};